function currency(n) {
  return (Number(n) || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}
function uid() {
  return Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
}
function isAreaUnit(unit) {
  if (!unit) return false;
  const norm = unit.trim().toLowerCase().replace(/\s/g, "").replace("²", "2");
  return norm === "cm2";
}
function resizeImageFile(file, maxDim = 320, quality = 0.72) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Falha ao ler arquivo"));
    reader.onload = () => {
      const img = new window.Image();
      img.onerror = () => reject(new Error("Falha ao carregar imagem"));
      img.onload = () => {
        let { width, height } = img;
        if (width > height && width > maxDim) {
          height = Math.round((height * maxDim) / width);
          width = maxDim;
        } else if (height > maxDim) {
          width = Math.round((width * maxDim) / height);
          height = maxDim;
        }
        const canvas = document.createElement("canvas");
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}
function emptyProductForm() {
  return { id: null, code: "", name: "", category: "Enfeites", unit: "un", qty: "", minStock: "", cost: "", laborCost: "", variableCost: "", price: "", recipe: [], photo: "", showInCatalog: true };
}
function emptyMaterialForm() {
  return { id: null, code: "", name: "", unit: "un", qty: "", minStock: "", cost: "", photo: "" };
}

export default function App() {
  const [data, setData] = useState(null);
  const [tab, setTab] = useState("produtos");
  const [query, setQuery] = useState("");
  const [activeCategory, setActiveCategory] = useState("Todas");
  const [showLowOnly, setShowLowOnly] = useState(false);
  const [productModal, setProductModal] = useState(false);
  const [materialModal, setMaterialModal] = useState(false);
  const [productForm, setProductForm] = useState(emptyProductForm());
  const [materialForm, setMaterialForm] = useState(emptyMaterialForm());
  const [confirmDelete, setConfirmDelete] = useState(null); // { kind, id }
  const [categoryModal, setCategoryModal] = useState(false);
  const [categoryDraft, setCategoryDraft] = useState([]);
  const [newCategoryName, setNewCategoryName] = useState("");
  const [saveError, setSaveError] = useState(false);
  const [moveAmounts, setMoveAmounts] = useState({}); // productId -> qty typed
  const [saleFeedback, setSaleFeedback] = useState(null);
  const [matMoveAmounts, setMatMoveAmounts] = useState({}); // materialId -> qty typed (perda/ajuste)
  const [purchaseTarget, setPurchaseTarget] = useState(null); // material being purchased
  const [purchaseForm, setPurchaseForm] = useState({ qty: "", total: "" });
  const [purchaseFeedback, setPurchaseFeedback] = useState(null);
  const [productError, setProductError] = useState("");
  const [materialError, setMaterialError] = useState("");
  const [purchaseError, setPurchaseError] = useState("");
  const [photoUploading, setPhotoUploading] = useState(false);

  async function handlePhotoChange(file, setForm) {
    if (!file) return;
    setPhotoUploading(true);
    try {
      const dataUrl = await resizeImageFile(file);
      setForm((f) => ({ ...f, photo: dataUrl }));
    } catch (e) {
      // silently ignore, keep previous photo
    } finally {
      setPhotoUploading(false);
    }
  }

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const result = await loadData();
        if (cancelled) return;
        if (result) {
          setData({
            ...result,
            categories: result.categories && result.categories.length ? result.categories : DEFAULT_CATEGORIES,
            products: (result.products || []).map((p) => ({ showInCatalog: true, ...p })),
          });
        } else setData(SEED);
      } catch (e) {
        if (!cancelled) setData(SEED);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const persist = useCallback(async (next) => {
    try {
      await saveData(next);
      setSaveError(false);
    } catch (e) {
      setSaveError(true);
    }
  }, []);

  const updateData = useCallback(
    (updater) => {
      setData((prev) => {
        const next = typeof updater === "function" ? updater(prev || SEED) : updater;
        persist(next);
        return next;
      });
    },
    [persist]
  );

  const materialsById = useMemo(() => {
    if (!data) return {};
    return Object.fromEntries(data.materials.map((m) => [m.id, m]));
  }, [data]);

  const recipeCostTotal = useMemo(() => {
    if (!productForm.recipe || !productForm.recipe.length) return 0;
    return productForm.recipe.reduce((sum, row) => {
      const mat = materialsById[row.materialId];
      const qty = Number(row.qty) || 0;
      if (!mat) return sum;
      return sum + qty * Number(mat.cost || 0);
    }, 0);
  }, [productForm.recipe, materialsById]);

  // sempre que houver ficha técnica, o custo de matéria-prima é puxado automaticamente dela
  useEffect(() => {
    if (productForm.recipe && productForm.recipe.length > 0) {
      const rounded = recipeCostTotal.toFixed(2);
      setProductForm((f) => (f.cost === rounded ? f : { ...f, cost: rounded }));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [recipeCostTotal, productForm.recipe.length]);

  const totalCostForm =
    (Number(productForm.cost) || 0) + (Number(productForm.laborCost) || 0) + (Number(productForm.variableCost) || 0);

  // ---------- filters ----------
  const filteredProducts = useMemo(() => {
    if (!data) return [];
    return data.products.filter((it) => {
      if (activeCategory !== "Todas" && it.category !== activeCategory) return false;
      if (showLowOnly && !(Number(it.qty) <= Number(it.minStock))) return false;
      if (query.trim()) {
        const q = query.toLowerCase();
        if (!it.name.toLowerCase().includes(q) && !it.code.toLowerCase().includes(q)) return false;
      }
      return true;
    });
  }, [data, activeCategory, showLowOnly, query]);

  const filteredMaterials = useMemo(() => {
    if (!data) return [];
    return data.materials.filter((it) => {
      if (showLowOnly && !(Number(it.qty) <= Number(it.minStock))) return false;
      if (query.trim()) {
        const q = query.toLowerCase();
        if (!it.name.toLowerCase().includes(q) && !it.code.toLowerCase().includes(q)) return false;
      }
      return true;
    });
  }, [data, showLowOnly, query]);

  const productStats = useMemo(() => {
    if (!data) return { total: 0, low: 0, value: 0 };
    const total = data.products.length;
    const low = data.products.filter((it) => Number(it.qty) <= Number(it.minStock)).length;
    const value = data.products.reduce((s, it) => s + Number(it.qty) * Number(it.cost), 0);
    return { total, low, value };
  }, [data]);

  const materialStats = useMemo(() => {
    if (!data) return { total: 0, low: 0, value: 0 };
    const total = data.materials.length;
    const low = data.materials.filter((it) => Number(it.qty) <= Number(it.minStock)).length;
    const value = data.materials.reduce((s, it) => s + Number(it.qty) * Number(it.cost), 0);
    return { total, low, value };
  }, [data]);

  // ---------- product CRUD ----------
  function openAddProduct() {
    setProductForm(emptyProductForm());
    setProductError("");
    setProductModal(true);
  }
  function openEditProduct(item) {
    const materialCost = item.materialCost !== undefined ? item.materialCost : item.cost;
    const laborCost = item.laborCost || 0;
    const variableCost = item.variableCost || 0;
    setProductForm({
      ...item,
      qty: String(item.qty),
      minStock: String(item.minStock),
      cost: String(materialCost),
      laborCost: String(laborCost),
      variableCost: String(variableCost),
      price: String(item.price),
      recipe: item.recipe ? item.recipe.map((r) => ({ ...r, qty: String(r.qty) })) : [],
      showInCatalog: item.showInCatalog !== false,
    });
    setProductError("");
    setProductModal(true);
  }
  function closeProductModal() {
    setProductModal(false);
    setProductForm(emptyProductForm());
    setProductError("");
  }
  function saveProduct() {
    if (!productForm.name.trim()) {
      setProductError("Informe o nome do produto.");
      return;
    }
    const materialCost = Number(productForm.cost) || 0;
    const laborCost = Number(productForm.laborCost) || 0;
    const variableCost = Number(productForm.variableCost) || 0;
    const payload = {
      id: productForm.id || uid(),
      code: productForm.code.trim() || "—",
      name: productForm.name.trim(),
      category: productForm.category,
      unit: productForm.unit.trim() || "un",
      qty: Number(productForm.qty) || 0,
      minStock: Number(productForm.minStock) || 0,
      materialCost: materialCost,
      laborCost: laborCost,
      variableCost: variableCost,
      cost: materialCost + laborCost + variableCost,
      price: Number(productForm.price) || 0,
      recipe: (productForm.recipe || [])
        .filter((r) => r.materialId)
        .map((r) => ({ materialId: r.materialId, qty: Number(r.qty) || 0 })),
      photo: productForm.photo || "",
      showInCatalog: productForm.showInCatalog !== false,
    };
    updateData((prev) => {
      const exists = prev.products.some((it) => it.id === payload.id);
      const products = exists
        ? prev.products.map((it) => (it.id === payload.id ? payload : it))
        : [...prev.products, payload];
      return { ...prev, products };
    });
    closeProductModal();
  }

  function addRecipeRow() {
    setProductForm((f) => ({ ...f, recipe: [...f.recipe, { materialId: "", qty: "" }] }));
  }
  function updateRecipeRow(idx, field, value) {
    setProductForm((f) => {
      const recipe = f.recipe.slice();
      recipe[idx] = { ...recipe[idx], [field]: value };
      return { ...f, recipe };
    });
  }
  function removeRecipeRow(idx) {
    setProductForm((f) => ({ ...f, recipe: f.recipe.filter((_, i) => i !== idx) }));
  }

  // ---------- material CRUD ----------
  function openAddMaterial() {
    setMaterialForm(emptyMaterialForm());
    setMaterialError("");
    setMaterialModal(true);
  }
  function openEditMaterial(item) {
    setMaterialForm({ ...item, qty: String(item.qty), minStock: String(item.minStock), cost: String(item.cost) });
    setMaterialError("");
    setMaterialModal(true);
  }
  function closeMaterialModal() {
    setMaterialModal(false);
    setMaterialForm(emptyMaterialForm());
    setMaterialError("");
  }
  function saveMaterial() {
    if (!materialForm.name.trim()) {
      setMaterialError("Informe o nome da matéria-prima.");
      return;
    }
    const payload = {
      id: materialForm.id || uid(),
      code: materialForm.code.trim() || "—",
      name: materialForm.name.trim(),
      unit: materialForm.unit.trim() || "un",
      qty: Number(materialForm.qty) || 0,
      minStock: Number(materialForm.minStock) || 0,
      cost: Number(materialForm.cost) || 0,
      photo: materialForm.photo || "",
    };
    updateData((prev) => {
      const exists = prev.materials.some((it) => it.id === payload.id);
      const materials = exists
        ? prev.materials.map((it) => (it.id === payload.id ? payload : it))
        : [...prev.materials, payload];
      return { ...prev, materials };
    });
    closeMaterialModal();
  }

  // ---------- gerenciar categorias ----------
  function openCategoryModal() {
    setCategoryDraft(data ? [...data.categories] : [...DEFAULT_CATEGORIES]);
    setNewCategoryName("");
    setCategoryModal(true);
  }
  function closeCategoryModal() {
    setCategoryModal(false);
  }
  function updateCategoryDraftName(idx, value) {
    setCategoryDraft((prev) => prev.map((c, i) => (i === idx ? value : c)));
  }
  function removeCategoryDraft(idx) {
    setCategoryDraft((prev) => prev.filter((_, i) => i !== idx));
  }
  function addCategoryDraft() {
    const name = newCategoryName.trim();
    if (!name) return;
    setCategoryDraft((prev) => [...prev, name]);
    setNewCategoryName("");
  }
  function saveCategories() {
    const original = data && data.categories ? data.categories : DEFAULT_CATEGORIES;
    const cleaned = categoryDraft.map((c) => c.trim()).filter(Boolean);
    if (cleaned.length === 0) return;
    // mapeia renomeações por posição para atualizar produtos existentes
    const renameMap = {};
    original.forEach((oldName, idx) => {
      const newName = categoryDraft[idx];
      if (newName && newName.trim() && newName.trim() !== oldName) {
        renameMap[oldName] = newName.trim();
      }
    });
    updateData((prev) => ({
      ...prev,
      categories: cleaned,
      products: prev.products.map((p) =>
        renameMap[p.category] ? { ...p, category: renameMap[p.category] } : p
      ),
    }));
    setCategoryModal(false);
  }

  function deleteEntity(kind, id) {
    updateData((prev) => {
      if (kind === "product") return { ...prev, products: prev.products.filter((it) => it.id !== id) };
      return { ...prev, materials: prev.materials.filter((it) => it.id !== id) };
    });
    setConfirmDelete(null);
  }

  // ---------- movement logic: saída de produto consome matéria-prima via ficha técnica ----------
  function registerMovement(product, direction) {
    const amount = Number(moveAmounts[product.id]) > 0 ? Number(moveAmounts[product.id]) : 1;
    updateData((prev) => {
      const products = prev.products.map((it) =>
        it.id === product.id ? { ...it, qty: Math.max(0, Number(it.qty) + direction * amount) } : it
      );
      let materials = prev.materials;
      let consumedSummary = [];
      if (direction < 0 && product.recipe && product.recipe.length) {
        materials = prev.materials.map((m) => {
          const ing = product.recipe.find((r) => r.materialId === m.id);
          if (!ing) return m;
          const consumed = ing.qty * amount;
          consumedSummary.push({ name: m.name, consumed, left: Number(m.qty) - consumed, unit: m.unit });
          return { ...m, qty: Number(m.qty) - consumed };
        });
      }
      if (consumedSummary.length) {
        setSaleFeedback({ productName: product.name, amount, items: consumedSummary });
      } else {
        setSaleFeedback(null);
      }
      return { ...prev, products, materials };
    });
    setMoveAmounts((prevAmt) => ({ ...prevAmt, [product.id]: "" }));
  }

  // ---------- compra de matéria-prima: recalcula custo médio ponderado ----------
  function openPurchase(material) {
    setPurchaseTarget(material);
    setPurchaseForm({ qty: "", total: "" });
    setPurchaseError("");
  }
  function closePurchase() {
    setPurchaseTarget(null);
    setPurchaseForm({ qty: "", total: "" });
    setPurchaseError("");
  }
  function submitPurchase() {
    const qty = Number(purchaseForm.qty);
    const total = Number(purchaseForm.total);
    if (!purchaseTarget || !(qty > 0) || !(total >= 0)) {
      setPurchaseError("Informe uma quantidade maior que zero e um valor total válido.");
      return;
    }
    updateData((prev) => {
      const materials = prev.materials.map((m) => {
        if (m.id !== purchaseTarget.id) return m;
        const newQty = Number(m.qty) + qty;
        const newCost = newQty > 0 ? (Number(m.qty) * Number(m.cost) + total) / newQty : m.cost;
        setPurchaseFeedback({
          name: m.name,
          boughtQty: qty,
          unit: m.unit,
          paid: total,
          unitCost: total / qty,
          newAvgCost: newCost,
          newQty,
        });
        return { ...m, qty: newQty, cost: newCost };
      });
      return { ...prev, materials };
    });
    closePurchase();
  }

  // perda/ajuste manual de matéria-prima (não mexe no custo médio)
  function adjustMaterialLoss(material) {
    const amount = Number(matMoveAmounts[material.id]) > 0 ? Number(matMoveAmounts[material.id]) : 1;
    updateData((prev) => ({
      ...prev,
      materials: prev.materials.map((m) => (m.id === material.id ? { ...m, qty: Math.max(0, Number(m.qty) - amount) } : m)),
    }));
    setMatMoveAmounts((p) => ({ ...p, [material.id]: "" }));
  }

  const loading = data === null;

  return (
    <div style={styles.page}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Jost:wght@300;400;500;600&display=swap');
        * { box-sizing: border-box; }
        body { margin: 0; }
        input, select { font-family: 'Work Sans', sans-serif; }
        ::placeholder { color: #A9A398; }
        button { cursor: pointer; font-family: 'Work Sans', sans-serif; }
        .row-hover:hover { background: #F3EEE4 !important; }
        .chip:hover { filter: brightness(0.97); }
        .tab-btn:hover { opacity: 0.85; }
        @media (max-width: 760px) {
          .stats-grid { grid-template-columns: 1fr 1fr !important; }
          .table-head { display: none !important; }
          .item-row { grid-template-columns: 1fr !important; row-gap: 6px; }
          .item-row > div { display: flex; justify-content: space-between; }
        }
      `}</style>

      <header style={styles.header}>
        <div style={styles.headerInner}>
          <div style={styles.brandRow}>
            <img src={LOGO_URL} alt="Mawi Florart" style={styles.brandLogo} />
            <div>
              <h1 style={styles.brandTitle}>MawiFlorart</h1>
              <p style={styles.brandSub}>controle de estoque &amp; matéria-prima</p>
            </div>
          </div>
          {tab !== "catalogo" && (
            <button style={styles.addBtn} onClick={tab === "produtos" ? openAddProduct : openAddMaterial}>
              <Plus size={18} />
              {tab === "produtos" ? "Novo produto" : "Nova matéria-prima"}
            </button>
          )}
        </div>
        <div style={styles.tabRow}>
          <button
            className="tab-btn"
            style={{ ...styles.tabBtn, ...(tab === "produtos" ? styles.tabBtnActive : {}) }}
            onClick={() => {
              setTab("produtos");
              setQuery("");
              setShowLowOnly(false);
            }}
          >
            Produtos
          </button>
          <button
            className="tab-btn"
            style={{ ...styles.tabBtn, ...(tab === "materia-prima" ? styles.tabBtnActive : {}) }}
            onClick={() => {
              setTab("materia-prima");
              setQuery("");
              setShowLowOnly(false);
            }}
          >
            Matéria-Prima
          </button>
          <button
            className="tab-btn"
            style={{ ...styles.tabBtn, ...(tab === "catalogo" ? styles.tabBtnActive : {}) }}
            onClick={() => {
              setTab("catalogo");
              setQuery("");
              setShowLowOnly(false);
            }}
          >
            Catálogo
          </button>
        </div>
      </header>

      <main style={styles.main}>
        {saleFeedback && (
          <div style={styles.feedbackBox}>
            <div style={styles.feedbackTitle}>
              Saída registrada: {saleFeedback.amount}x {saleFeedback.productName}
            </div>
            <div style={styles.feedbackGrid}>
              {saleFeedback.items.map((it, i) => (
                <div key={i} style={styles.feedbackItem}>
                  <span>{it.name}</span>
                  <span>
                    gastou {it.consumed} {it.unit} · sobrou{" "}
                    <strong style={{ color: it.left < 0 ? "#B15768" : "#1F3A2E" }}>
                      {it.left} {it.unit}
                    </strong>
                  </span>
                </div>
              ))}
            </div>
            <button style={styles.feedbackClose} onClick={() => setSaleFeedback(null)}>
              <X size={14} />
            </button>
          </div>
        )}

        {tab === "produtos" ? (
          <>
            <section className="stats-grid" style={styles.statsGrid}>
              <StatCard label="Produtos cadastrados" value={productStats.total} />
              <StatCard
                label="Estoque baixo"
                value={productStats.low}
                tone={productStats.low > 0 ? "warn" : "ok"}
                icon={productStats.low > 0 ? AlertTriangle : undefined}
              />
              <StatCard label="Valor em estoque" value={currency(productStats.value)} />
            </section>

            <Toolbar
              query={query}
              setQuery={setQuery}
              showLowOnly={showLowOnly}
              setShowLowOnly={setShowLowOnly}
              chips={
                <div style={styles.chipRow}>
                  <button
                    className="chip"
                    style={{ ...styles.chip, ...(activeCategory === "Todas" ? styles.chipActive : {}) }}
                    onClick={() => setActiveCategory("Todas")}
                  >
                    Todas
                  </button>
                  {(data && data.categories ? data.categories : DEFAULT_CATEGORIES).map((c) => (
                    <button
                      key={c}
                      className="chip"
                      style={{ ...styles.chip, ...(activeCategory === c ? styles.chipActive : {}) }}
                      onClick={() => setActiveCategory(c)}
                    >
                      {c}
                    </button>
                  ))}
                  <button className="chip" style={styles.chip} onClick={openCategoryModal}>
                    gerenciar categorias
                  </button>
                </div>
              }
            />

            <section style={styles.tableWrap}>
              <div className="table-head" style={{ ...styles.tableHead, gridTemplateColumns: "2fr 1fr 1fr 1.6fr 1.3fr" }}>
                <span>Produto</span>
                <span style={styles.centerCol}>Estoque / Mínimo</span>
                <span style={styles.rightCol}>Custo / Venda</span>
                <span style={styles.centerCol}>Registrar movimento</span>
                <span style={styles.rightCol}>Ações</span>
              </div>

              {loading && <div style={styles.emptyState}>Carregando estoque…</div>}
              {!loading && filteredProducts.length === 0 && (
                <div style={styles.emptyState}>Nenhum produto encontrado. Ajuste os filtros ou cadastre um novo.</div>
              )}

              {!loading &&
                filteredProducts.map((it) => {
                  const Icon = getCategoryIcon(it.category);
                  const low = Number(it.qty) <= Number(it.minStock);
                  const hasRecipe = it.recipe && it.recipe.length > 0;
                  return (
                    <div
                      key={it.id}
                      className="item-row row-hover"
                      style={{ ...styles.itemRow, gridTemplateColumns: "2fr 1fr 1fr 1.6fr 1.3fr" }}
                    >
                      <div style={styles.productCell}>
                        <div style={{ ...styles.iconBadge, background: low ? "#F3DCE0" : "#E7EFE9" }}>
                          {it.photo ? (
                            <img src={it.photo} alt={it.name} style={styles.thumbImg} />
                          ) : (
                            <Icon size={16} color={low ? "#B15768" : "#1F3A2E"} />
                          )}
                        </div>
                        <div style={{ minWidth: 0 }}>
                          <div style={styles.productName}>{it.name}</div>
                          <div style={styles.productCode}>
                            {it.code} · {it.unit}
                            {hasRecipe && (
                              <span style={styles.recipeTag}>
                                <Layers size={11} style={{ marginRight: 3, verticalAlign: -1.5 }} />
                                {it.recipe.length} ingrediente{it.recipe.length > 1 ? "s" : ""}
                              </span>
                            )}
                            {it.showInCatalog === false && <span style={styles.hiddenTag}>oculto do catálogo</span>}
                          </div>
                        </div>
                      </div>
                      <div style={{ ...styles.centerCol, fontWeight: 600, color: low ? "#B15768" : "#2A2620" }}>
                        {it.qty} / {it.minStock}
                      </div>
                      <div style={styles.rightCol}>
                        <div>{currency(it.cost)}</div>
                        <div style={{ color: "#8A8375", fontSize: 12 }}>{currency(it.price)}</div>
                      </div>
                      <div style={{ ...styles.moveCell }}>
                        <input
                          type="number"
                          min="1"
                          placeholder="1"
                          value={moveAmounts[it.id] || ""}
                          onChange={(e) => setMoveAmounts((p) => ({ ...p, [it.id]: e.target.value }))}
                          style={styles.moveInput}
                        />
                        <button
                          title="Registrar entrada (produção/compra)"
                          style={{ ...styles.moveBtn, color: "#1F3A2E" }}
                          onClick={() => registerMovement(it, 1)}
                        >
                          <ArrowUpCircle size={16} />
                        </button>
                        <button
                          title="Registrar saída (venda) — desconta a ficha técnica"
                          style={{ ...styles.moveBtn, color: "#B15768" }}
                          onClick={() => registerMovement(it, -1)}
                        >
                          <ArrowDownCircle size={16} />
                        </button>
                      </div>
                      <div style={{ ...styles.rightCol, display: "flex", gap: 6, justifyContent: "flex-end" }}>
                        <button style={styles.iconBtn} onClick={() => openEditProduct(it)} aria-label="Editar">
                          <Pencil size={14} />
                        </button>
                        <button
                          style={{ ...styles.iconBtn, color: "#B15768" }}
                          onClick={() => setConfirmDelete({ kind: "product", id: it.id })}
                          aria-label="Excluir"
                        >
                          <Trash2 size={14} />
                        </button>
                      </div>
                    </div>
                  );
                })}
            </section>
          </>
        ) : tab === "materia-prima" ? (
          <>
            <section className="stats-grid" style={styles.statsGrid}>
              <StatCard label="Matérias-primas cadastradas" value={materialStats.total} />
              <StatCard
                label="Estoque baixo"
                value={materialStats.low}
                tone={materialStats.low > 0 ? "warn" : "ok"}
                icon={materialStats.low > 0 ? AlertTriangle : undefined}
              />
              <StatCard label="Valor em estoque" value={currency(materialStats.value)} />
            </section>

            <Toolbar query={query} setQuery={setQuery} showLowOnly={showLowOnly} setShowLowOnly={setShowLowOnly} />

            <section style={styles.tableWrap}>
              <div className="table-head" style={{ ...styles.tableHead, gridTemplateColumns: "1.8fr 1fr 1fr 1.5fr 1fr" }}>
                <span>Matéria-prima</span>
                <span style={styles.centerCol}>Estoque (sobra) / Mínimo</span>
                <span style={styles.rightCol}>Custo médio</span>
                <span style={styles.centerCol}>Movimento</span>
                <span style={styles.rightCol}>Ações</span>
              </div>

              {loading && <div style={styles.emptyState}>Carregando…</div>}
              {!loading && filteredMaterials.length === 0 && (
                <div style={styles.emptyState}>Nenhuma matéria-prima encontrada.</div>
              )}

              {!loading &&
                filteredMaterials.map((it) => {
                  const low = Number(it.qty) <= Number(it.minStock);
                  return (
                    <div key={it.id} className="item-row row-hover" style={{ ...styles.itemRow, gridTemplateColumns: "1.8fr 1fr 1fr 1.5fr 1fr" }}>
                      <div style={styles.productCell}>
                        <div style={{ ...styles.iconBadge, background: low ? "#F3DCE0" : "#E7EFE9" }}>
                          {it.photo ? (
                            <img src={it.photo} alt={it.name} style={styles.thumbImg} />
                          ) : (
                            <Sparkles size={16} color={low ? "#B15768" : "#1F3A2E"} />
                          )}
                        </div>
                        <div>
                          <div style={styles.productName}>{it.name}</div>
                          <div style={styles.productCode}>
                            {it.code} · {it.unit}
                          </div>
                        </div>
                      </div>
                      <div style={{ ...styles.centerCol, fontWeight: 600, color: low ? "#B15768" : "#2A2620" }}>
                        {it.qty} / {it.minStock}
                      </div>
                      <div style={styles.rightCol}>
                        <div>{currency(it.cost)}</div>
                        <div style={{ color: "#B0A599", fontSize: 11 }}>por {it.unit}</div>
                      </div>
                      <div style={styles.moveCell}>
                        <input
                          type="number"
                          min="1"
                          placeholder="1"
                          value={matMoveAmounts[it.id] || ""}
                          onChange={(e) => setMatMoveAmounts((p) => ({ ...p, [it.id]: e.target.value }))}
                          style={styles.moveInput}
                        />
                        <button
                          title="Registrar perda/ajuste (não altera o custo médio)"
                          style={{ ...styles.moveBtn, color: "#B15768" }}
                          onClick={() => adjustMaterialLoss(it)}
                        >
                          <ArrowDownCircle size={16} />
                        </button>
                        <button
                          title="Registrar compra (informe quantidade e valor total)"
                          style={{ ...styles.moveBtn, color: "#1F3A2E" }}
                          onClick={() => openPurchase(it)}
                        >
                          <ShoppingCart size={15} />
                        </button>
                      </div>
                      <div style={{ ...styles.rightCol, display: "flex", gap: 6, justifyContent: "flex-end" }}>
                        <button style={styles.iconBtn} onClick={() => openEditMaterial(it)} aria-label="Editar">
                          <Pencil size={14} />
                        </button>
                        <button
                          style={{ ...styles.iconBtn, color: "#B15768" }}
                          onClick={() => setConfirmDelete({ kind: "material", id: it.id })}
                          aria-label="Excluir"
                        >
                          <Trash2 size={14} />
                        </button>
                      </div>
                    </div>
                  );
                })}
            </section>

            {purchaseFeedback && (
              <div style={{ ...styles.feedbackBox, marginTop: 16 }}>
                <div style={styles.feedbackTitle}>
                  Compra registrada: {purchaseFeedback.boughtQty} {purchaseFeedback.unit} de {purchaseFeedback.name}
                </div>
                <div style={styles.feedbackGrid}>
                  <div style={styles.feedbackItem}>
                    <span>Pago no total</span>
                    <span>{currency(purchaseFeedback.paid)}</span>
                  </div>
                  <div style={styles.feedbackItem}>
                    <span>Custo desta compra (por unidade)</span>
                    <span>{currency(purchaseFeedback.unitCost)}</span>
                  </div>
                  <div style={styles.feedbackItem}>
                    <span>Novo custo médio</span>
                    <strong>{currency(purchaseFeedback.newAvgCost)}</strong>
                  </div>
                  <div style={styles.feedbackItem}>
                    <span>Novo estoque</span>
                    <strong>
                      {purchaseFeedback.newQty} {purchaseFeedback.unit}
                    </strong>
                  </div>
                </div>
                <button style={styles.feedbackClose} onClick={() => setPurchaseFeedback(null)}>
                  <X size={14} />
                </button>
              </div>
            )}
          </>
        ) : (
          <CatalogoTab products={data ? data.products : []} loading={loading} query={query} setQuery={setQuery} />
        )}

        {saveError && <p style={styles.saveError}>Não foi possível salvar as alterações agora. Tente novamente.</p>}
      </main>

      {productModal && (
        <div style={styles.overlay} onClick={closeProductModal}>
          <div style={styles.modal} onClick={(e) => e.stopPropagation()}>
            <div style={styles.modalHeader}>
              <h2 style={styles.modalTitle}>{productForm.id ? "Editar produto" : "Novo produto"}</h2>
              <button type="button" style={styles.iconBtn} onClick={closeProductModal} aria-label="Fechar">
                <X size={18} />
              </button>
            </div>

            <PhotoPicker
              photo={productForm.photo}
              uploading={photoUploading}
              onChange={(file) => handlePhotoChange(file, setProductForm)}
              onRemove={() => setProductForm((f) => ({ ...f, photo: "" }))}
            />

            <label style={styles.catalogToggle}>
              <input
                type="checkbox"
                checked={productForm.showInCatalog !== false}
                onChange={(e) => setProductForm({ ...productForm, showInCatalog: e.target.checked })}
              />
              Mostrar este produto no Catálogo (visível para os clientes)
            </label>

            <div style={styles.formGrid}>
              <Field label="Código">
                <input style={styles.input} value={productForm.code} onChange={(e) => setProductForm({ ...productForm, code: e.target.value })} />
              </Field>
              <Field label="Nome do produto" full>
                <input style={styles.input} value={productForm.name} onChange={(e) => setProductForm({ ...productForm, name: e.target.value })} />
              </Field>
              <Field label="Categoria">
                <select style={styles.input} value={productForm.category} onChange={(e) => setProductForm({ ...productForm, category: e.target.value })}>
                  {(data && data.categories ? data.categories : DEFAULT_CATEGORIES).map((c) => (
                    <option key={c} value={c}>
                      {c}
                    </option>
                  ))}
                </select>
              </Field>
              <Field label="Unidade">
                <input style={styles.input} value={productForm.unit} onChange={(e) => setProductForm({ ...productForm, unit: e.target.value })} placeholder="un, kit…" />
              </Field>
              <Field label="Quantidade atual">
                <input style={styles.input} type="number" min="0" value={productForm.qty} onChange={(e) => setProductForm({ ...productForm, qty: e.target.value })} />
              </Field>
              <Field label="Estoque mínimo">
                <input style={styles.input} type="number" min="0" value={productForm.minStock} onChange={(e) => setProductForm({ ...productForm, minStock: e.target.value })} />
              </Field>
              <Field label={productForm.recipe.length > 0 ? "Custo de matéria-prima (R$) — automático da ficha técnica" : "Custo de matéria-prima (R$)"}>
                <input
                  style={{ ...styles.input, ...(productForm.recipe.length > 0 ? styles.inputReadonly : {}) }}
                  type="number"
                  min="0"
                  step="0.01"
                  value={productForm.cost}
                  readOnly={productForm.recipe.length > 0}
                  onChange={(e) => setProductForm({ ...productForm, cost: e.target.value })}
                />
              </Field>
              <Field label="Custo de mão de obra (R$)">
                <input style={styles.input} type="number" min="0" step="0.01" value={productForm.laborCost} onChange={(e) => setProductForm({ ...productForm, laborCost: e.target.value })} />
              </Field>
              <Field label="Custos variáveis (R$) — luz, taxa de maquininha etc.">
                <input style={styles.input} type="number" min="0" step="0.01" value={productForm.variableCost} onChange={(e) => setProductForm({ ...productForm, variableCost: e.target.value })} />
              </Field>
              <Field label="Preço de venda (R$)">
                <input style={styles.input} type="number" min="0" step="0.01" value={productForm.price} onChange={(e) => setProductForm({ ...productForm, price: e.target.value })} />
              </Field>
            </div>

            <div style={styles.recipeTotalBox}>
              <span>Custo total (matéria-prima + mão de obra + custos variáveis)</span>
              <strong>{currency(totalCostForm)}</strong>
            </div>

            <ProfitCalc totalCost={totalCostForm} price={Number(productForm.price) || 0} onUsePrice={(p) => setProductForm((f) => ({ ...f, price: p }))} />

            <div style={styles.recipeSection}>
              <div style={styles.recipeSectionHeader}>
                <span style={styles.fieldLabelText}>Ficha técnica (matéria-prima usada por unidade)</span>
                <button type="button" style={styles.smallAddBtn} onClick={addRecipeRow}>
                  <Plus size={13} /> ingrediente
                </button>
              </div>
              {(!data || data.materials.length === 0) && (
                <p style={styles.hint}>Cadastre matérias-primas na aba "Matéria-Prima" para montar a ficha técnica.</p>
              )}
              {productForm.recipe.length === 0 && data && data.materials.length > 0 && (
                <p style={styles.hint}>Nenhum ingrediente adicionado. Sem ficha técnica, a saída não desconta matéria-prima.</p>
              )}
              {productForm.recipe.map((row, idx) => {
                const mat = materialsById[row.materialId];
                const rowQty = Number(row.qty) || 0;
                const rowCost = mat ? rowQty * Number(mat.cost || 0) : 0;
                return (
                  <div key={idx} style={styles.recipeRowWrap}>
                    <div style={styles.recipeRow}>
                      <select
                        style={{ ...styles.input, flex: 2 }}
                        value={row.materialId}
                        onChange={(e) => updateRecipeRow(idx, "materialId", e.target.value)}
                      >
                        <option value="">Selecione…</option>
                        {data &&
                          data.materials.map((m) => (
                            <option key={m.id} value={m.id}>
                              {m.name} ({currency(m.cost)}/{m.unit})
                            </option>
                          ))}
                      </select>
                      <input
                        style={{ ...styles.input, flex: 1 }}
                        type="number"
                        min="0"
                        step="0.01"
                        placeholder={mat ? `qtd em ${mat.unit}` : "qtd/un"}
                        value={row.qty}
                        onChange={(e) => updateRecipeRow(idx, "qty", e.target.value)}
                      />
                      <button type="button" style={styles.iconBtn} onClick={() => removeRecipeRow(idx)} aria-label="Remover ingrediente">
                        <X size={14} />
                      </button>
                    </div>
                    {mat && isAreaUnit(mat.unit) && (
                      <AreaCalcHelper onApply={(area) => updateRecipeRow(idx, "qty", String(area))} />
                    )}
                    {mat && rowQty > 0 && (
                      <div style={styles.recipeRowCost}>
                        {rowQty} {mat.unit} × {currency(mat.cost)} = <strong>{currency(rowCost)}</strong>
                      </div>
                    )}
                  </div>
                );
              })}
              {productForm.recipe.length > 0 && recipeCostTotal > 0 && (
                <div style={styles.recipeTotalBox}>
                  <span>Custo total da ficha técnica</span>
                  <div style={styles.recipeTotalRight}>
                    <strong>{currency(recipeCostTotal)}</strong>
                    <button
                      type="button"
                      style={styles.smallAddBtn}
                      onClick={() => setProductForm((f) => ({ ...f, cost: recipeCostTotal.toFixed(2) }))}
                    >
                      usar como custo
                    </button>
                  </div>
                </div>
              )}
            </div>

            {productError && <p style={styles.formError}>{productError}</p>}

            <div style={styles.modalActions}>
              <button type="button" style={styles.secondaryBtn} onClick={closeProductModal}>
                Cancelar
              </button>
              <button type="button" style={styles.primaryBtn} onClick={saveProduct}>
                {productForm.id ? "Salvar alterações" : "Adicionar produto"}
              </button>
            </div>
          </div>
        </div>
      )}

      {materialModal && (
        <div style={styles.overlay} onClick={closeMaterialModal}>
          <div style={styles.modal} onClick={(e) => e.stopPropagation()}>
            <div style={styles.modalHeader}>
              <h2 style={styles.modalTitle}>{materialForm.id ? "Editar matéria-prima" : "Nova matéria-prima"}</h2>
              <button type="button" style={styles.iconBtn} onClick={closeMaterialModal} aria-label="Fechar">
                <X size={18} />
              </button>
            </div>
            <PhotoPicker
              photo={materialForm.photo}
              uploading={photoUploading}
              onChange={(file) => handlePhotoChange(file, setMaterialForm)}
              onRemove={() => setMaterialForm((f) => ({ ...f, photo: "" }))}
            />
            <div style={styles.formGrid}>
              <Field label="Código">
                <input style={styles.input} value={materialForm.code} onChange={(e) => setMaterialForm({ ...materialForm, code: e.target.value })} />
              </Field>
              <Field label="Nome" full>
                <input style={styles.input} value={materialForm.name} onChange={(e) => setMaterialForm({ ...materialForm, name: e.target.value })} />
              </Field>
              <Field label="Unidade">
                <input style={styles.input} value={materialForm.unit} onChange={(e) => setMaterialForm({ ...materialForm, unit: e.target.value })} placeholder="un, m, kg…" />
              </Field>
              <Field label="Quantidade atual">
                <input style={styles.input} type="number" min="0" value={materialForm.qty} onChange={(e) => setMaterialForm({ ...materialForm, qty: e.target.value })} />
              </Field>
              <Field label="Estoque mínimo">
                <input style={styles.input} type="number" min="0" value={materialForm.minStock} onChange={(e) => setMaterialForm({ ...materialForm, minStock: e.target.value })} />
              </Field>
              <Field label={`Custo médio por ${materialForm.unit || "un"} (R$)`}>
                <input style={styles.input} type="number" min="0" step="0.01" value={materialForm.cost} onChange={(e) => setMaterialForm({ ...materialForm, cost: e.target.value })} />
              </Field>
            </div>

            <RestockHelper
              unitLabel={materialForm.unit || "un"}
              currentQty={materialForm.qty}
              currentCost={materialForm.cost}
              onApply={({ qty, cost }) => setMaterialForm((f) => ({ ...f, qty, cost }))}
            />
            {materialError && <p style={styles.formError}>{materialError}</p>}
            <div style={styles.modalActions}>
              <button type="button" style={styles.secondaryBtn} onClick={closeMaterialModal}>
                Cancelar
              </button>
              <button type="button" style={styles.primaryBtn} onClick={saveMaterial}>
                {materialForm.id ? "Salvar alterações" : "Adicionar matéria-prima"}
              </button>
            </div>
          </div>
        </div>
      )}

      {purchaseTarget && (
        <div style={styles.overlay} onClick={closePurchase}>
          <div style={styles.modal} onClick={(e) => e.stopPropagation()}>
            <div style={styles.modalHeader}>
              <h2 style={styles.modalTitle}>Registrar compra</h2>
              <button type="button" style={styles.iconBtn} onClick={closePurchase} aria-label="Fechar">
                <X size={18} />
              </button>
            </div>
            <p style={styles.hint}>
              {purchaseTarget.name} — estoque atual: {purchaseTarget.qty} {purchaseTarget.unit} · custo médio atual:{" "}
              {currency(purchaseTarget.cost)}
            </p>
            <div style={styles.formGrid}>
              <Field label={`Quantidade comprada (${purchaseTarget.unit})`}>
                <input
                  style={styles.input}
                  type="number"
                  min="0.01"
                  step="0.01"
                  autoFocus
                  value={purchaseForm.qty}
                  onChange={(e) => setPurchaseForm({ ...purchaseForm, qty: e.target.value })}
                />
                {isAreaUnit(purchaseTarget.unit) && (
                  <AreaCalcHelper onApply={(area) => setPurchaseForm((f) => ({ ...f, qty: String(area) }))} />
                )}
              </Field>
              <Field label="Valor total pago (R$)">
                <input
                  style={styles.input}
                  type="number"
                  min="0"
                  step="0.01"
                  value={purchaseForm.total}
                  onChange={(e) => setPurchaseForm({ ...purchaseForm, total: e.target.value })}
                />
              </Field>
            </div>
            {Number(purchaseForm.qty) > 0 && purchaseForm.total !== "" && (
              <p style={styles.hint}>
                Custo desta compra: {currency(Number(purchaseForm.total) / Number(purchaseForm.qty))} por {purchaseTarget.unit} — o
                custo médio será recalculado com o que já está em estoque.
              </p>
            )}
            {purchaseError && <p style={styles.formError}>{purchaseError}</p>}
            <div style={styles.modalActions}>
              <button type="button" style={styles.secondaryBtn} onClick={closePurchase}>
                Cancelar
              </button>
              <button type="button" style={styles.primaryBtn} onClick={submitPurchase}>
                Registrar compra
              </button>
            </div>
          </div>
        </div>
      )}

      {categoryModal && (
        <div style={styles.overlay} onClick={closeCategoryModal}>
          <div style={styles.modal} onClick={(e) => e.stopPropagation()}>
            <div style={styles.modalHeader}>
              <h2 style={styles.modalTitle}>Gerenciar categorias</h2>
              <button type="button" style={styles.iconBtn} onClick={closeCategoryModal} aria-label="Fechar">
                <X size={18} />
              </button>
            </div>
            <p style={styles.hint}>
              Renomear uma categoria já atualiza automaticamente os produtos que a usam. Remover uma categoria
              não apaga produtos, eles só deixam de aparecer nesse filtro.
            </p>
            {categoryDraft.map((c, idx) => (
              <div key={idx} style={styles.recipeRow}>
                <input
                  style={{ ...styles.input, flex: 1 }}
                  value={c}
                  onChange={(e) => updateCategoryDraftName(idx, e.target.value)}
                />
                <button type="button" style={styles.iconBtn} onClick={() => removeCategoryDraft(idx)} aria-label="Remover categoria">
                  <X size={14} />
                </button>
              </div>
            ))}
            <div style={{ ...styles.recipeRow, marginTop: 10 }}>
              <input
                style={{ ...styles.input, flex: 1 }}
                placeholder="nova categoria"
                value={newCategoryName}
                onChange={(e) => setNewCategoryName(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && addCategoryDraft()}
              />
              <button type="button" style={styles.smallAddBtn} onClick={addCategoryDraft}>
                <Plus size={13} /> adicionar
              </button>
            </div>
            <div style={styles.modalActions}>
              <button type="button" style={styles.secondaryBtn} onClick={closeCategoryModal}>
                Cancelar
              </button>
              <button type="button" style={styles.primaryBtn} onClick={saveCategories}>
                Salvar categorias
              </button>
            </div>
          </div>
        </div>
      )}

      {confirmDelete && (
        <div style={styles.overlay} onClick={() => setConfirmDelete(null)}>
          <div style={styles.confirmBox} onClick={(e) => e.stopPropagation()}>
            <p style={styles.confirmText}>
              Excluir {confirmDelete.kind === "product" ? "este produto" : "esta matéria-prima"} do estoque? Essa ação não pode ser
              desfeita.
            </p>
            <div style={styles.modalActions}>
              <button style={styles.secondaryBtn} onClick={() => setConfirmDelete(null)}>
                Cancelar
              </button>
              <button style={styles.dangerBtn} onClick={() => deleteEntity(confirmDelete.kind, confirmDelete.id)}>
                Excluir
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function Toolbar({ query, setQuery, showLowOnly, setShowLowOnly, chips }) {
  return (
    <section style={styles.toolbar}>
      <div style={styles.searchWrap}>
        <Search size={16} color="#8A8375" />
        <input style={styles.searchInput} placeholder="Buscar por nome ou código…" value={query} onChange={(e) => setQuery(e.target.value)} />
      </div>
      <div style={styles.chipRow}>
        {chips}
        <button
          className="chip"
          style={{ ...styles.chip, ...(showLowOnly ? styles.chipWarnActive : {}), marginLeft: chips ? 4 : 0 }}
          onClick={() => setShowLowOnly((v) => !v)}
        >
          <AlertTriangle size={13} style={{ marginRight: 4, verticalAlign: -2 }} />
          Estoque baixo
        </button>
      </div>
    </section>
  );
}

function StatCard({ label, value, tone, icon: Icon }) {
  const toneColor = tone === "warn" ? "#B15768" : "#1F3A2E";
  return (
    <div style={styles.statCard}>
      <div style={styles.statLabel}>{label}</div>
      <div style={{ ...styles.statValue, color: toneColor, display: "flex", alignItems: "center", gap: 8 }}>
        {Icon && <Icon size={20} />}
        {value}
      </div>
    </div>
  );
}

function ProfitCalc({ totalCost, price, onUsePrice }) {
  const [targetMargin, setTargetMargin] = useState("50");
  const hasCost = totalCost > 0;
  const profitValue = price - totalCost;
  const marginOverCost = hasCost && totalCost > 0 ? (profitValue / totalCost) * 100 : 0;
  const marginOverPrice = price > 0 ? (profitValue / price) * 100 : 0;
  const suggestedPrice = hasCost ? totalCost * (1 + (Number(targetMargin) || 0) / 100) : 0;

  return (
    <div style={styles.profitBox}>
      <div style={styles.profitRow}>
        <span>Lucro na venda atual</span>
        <strong style={{ color: profitValue >= 0 ? "#3E6B52" : "#B15768" }}>
          {price > 0 ? currency(profitValue) : "—"}
          {price > 0 && hasCost ? ` (${marginOverCost.toFixed(0)}% sobre o custo, ${marginOverPrice.toFixed(0)}% sobre a venda)` : ""}
        </strong>
      </div>
      <div style={styles.profitSuggestRow}>
        <span>Preço sugerido para uma margem de</span>
        <input
          style={styles.profitMarginInput}
          type="number"
          min="0"
          step="1"
          value={targetMargin}
          onChange={(e) => setTargetMargin(e.target.value)}
        />
        <span>% sobre o custo:</span>
        <strong>{hasCost ? currency(suggestedPrice) : "—"}</strong>
        {hasCost && (
          <button type="button" style={styles.smallAddBtn} onClick={() => onUsePrice(suggestedPrice.toFixed(2))}>
            usar este preço
          </button>
        )}
      </div>
    </div>
  );
}

function RestockHelper({ unitLabel, currentQty, currentCost, onApply }) {
  const [qty, setQty] = useState("");
  const [total, setTotal] = useState("");
  const boughtQty = Number(qty) || 0;
  const boughtTotal = Number(total) || 0;
  const baseQty = Number(currentQty) || 0;
  const baseCost = Number(currentCost) || 0;
  const newQty = baseQty + boughtQty;
  const weightedCost = boughtQty > 0 ? (baseQty * baseCost + boughtTotal) / newQty : 0;

  useEffect(() => {
    if (boughtQty <= 0 || total === "") return;
    const timer = setTimeout(() => {
      onApply({ qty: String(newQty), cost: weightedCost.toFixed(4) });
      setQty("");
      setTotal("");
    }, 700);
    return () => clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [qty, total]);

  return (
    <div style={styles.restockBox}>
      <div style={styles.restockLabel}>Reabastecer (opcional) — recalcula o custo médio automaticamente</div>
      <div style={styles.areaHelperBox}>
        <input
          style={{ ...styles.input, ...styles.areaInput }}
          type="number"
          min="0"
          step="0.01"
          placeholder={`qtd comprada (${unitLabel || "un"})`}
          value={qty}
          onChange={(e) => setQty(e.target.value)}
        />
        <span style={styles.areaX}>por</span>
        <input
          style={{ ...styles.input, ...styles.areaInput }}
          type="number"
          min="0"
          step="0.01"
          placeholder="valor total R$"
          value={total}
          onChange={(e) => setTotal(e.target.value)}
        />
      </div>
      {isAreaUnit(unitLabel) && <AreaCalcHelper onApply={(area) => setQty(String(area))} />}
      {boughtQty > 0 && total !== "" && (
        <div style={styles.restockPreview}>
          aplicando em instantes: novo estoque <strong>{newQty} {unitLabel}</strong> · novo custo médio{" "}
          <strong>{currency(weightedCost)}</strong> / {unitLabel}
        </div>
      )}
    </div>
  );
}

function AreaCalcHelper({ onApply }) {
  const [open, setOpen] = useState(false);
  const [w, setW] = useState("");
  const [h, setH] = useState("");
  const area = (Number(w) || 0) * (Number(h) || 0);
  return (
    <div style={styles.areaHelper}>
      <button type="button" style={styles.areaToggle} onClick={() => setOpen((v) => !v)}>
        {open ? "fechar calculadora de área" : "calcular por medida (cm)"}
      </button>
      {open && (
        <div style={styles.areaHelperBox}>
          <input
            style={{ ...styles.input, ...styles.areaInput }}
            type="number"
            min="0"
            step="0.1"
            placeholder="largura cm"
            value={w}
            onChange={(e) => setW(e.target.value)}
          />
          <span style={styles.areaX}>×</span>
          <input
            style={{ ...styles.input, ...styles.areaInput }}
            type="number"
            min="0"
            step="0.1"
            placeholder="altura cm"
            value={h}
            onChange={(e) => setH(e.target.value)}
          />
          <button
            type="button"
            style={styles.smallAddBtn}
            disabled={!area}
            onClick={() => {
              onApply(area);
              setOpen(false);
              setW("");
              setH("");
            }}
          >
            usar {area > 0 ? `${area} cm²` : "—"}
          </button>
        </div>
      )}
    </div>
  );
}

function PhotoPicker({ photo, uploading, onChange, onRemove }) {
  const inputId = useMemo(() => "photo-" + Math.random().toString(36).slice(2, 9), []);
  return (
    <div style={styles.photoPicker}>
      <div style={styles.photoPreview}>
        {photo ? (
          <img src={photo} alt="Foto" style={styles.photoImg} />
        ) : (
          <Camera size={22} color="#A9A398" />
        )}
      </div>
      <div style={styles.photoActions}>
        <label htmlFor={inputId} style={styles.photoUploadBtn}>
          <ImageIcon size={13} style={{ marginRight: 5, verticalAlign: -2 }} />
          {uploading ? "Enviando…" : photo ? "Trocar foto" : "Adicionar foto"}
        </label>
        <input
          id={inputId}
          type="file"
          accept="image/*"
          style={{ display: "none" }}
          onChange={(e) => {
            const file = e.target.files && e.target.files[0];
            onChange(file);
            e.target.value = "";
          }}
        />
        {photo && (
          <button type="button" style={styles.photoRemoveBtn} onClick={onRemove}>
            Remover
          </button>
        )}
      </div>
    </div>
  );
}

function CatalogoTab({ products, loading, query, setQuery }) {
  const filtered = (products || [])
    .filter((p) => p.showInCatalog !== false)
    .filter((p) => {
      if (query.trim() && !p.name.toLowerCase().includes(query.toLowerCase())) return false;
      return true;
    });

  return (
    <>
      <div style={styles.catalogIntro}>
        Esta é a visão que seus clientes veem — sem custos nem estoque, só nome, foto e preço.
      </div>
      <Toolbar query={query} setQuery={setQuery} showLowOnly={false} setShowLowOnly={() => {}} />
      {loading ? (
        <div style={styles.emptyState}>Carregando…</div>
      ) : filtered.length === 0 ? (
        <div style={styles.emptyState}>Nenhum produto encontrado.</div>
      ) : (
        <section className="grid" style={styles.catalogGrid}>
          {filtered.map((p) => (
            <div key={p.id} style={styles.catalogCard}>
              <div style={styles.catalogCardImg}>
                {p.photo ? <img src={p.photo} alt={p.name} style={styles.catalogCardPhoto} /> : <Flower2 size={26} color="#D9C3C8" />}
              </div>
              <div style={styles.catalogCardBody}>
                <div style={styles.catalogCardCategory}>{p.category}</div>
                <div style={styles.catalogCardName}>{p.name}</div>
                <div style={styles.catalogCardFooter}>
                  <span style={styles.catalogCardPrice}>{currency(p.price)}</span>
                  <a href={whatsappLink(p.name)} target="_blank" rel="noreferrer" style={styles.catalogWaBtn} title="Pedir pelo WhatsApp">
                    <MessageCircle size={13} />
                  </a>
                </div>
              </div>
            </div>
          ))}
        </section>
      )}
    </>
  );
}

function Field({ label, children, full }) {
  return (
    <label style={{ ...styles.fieldLabel, gridColumn: full ? "1 / -1" : undefined }}>
      <span style={styles.fieldLabelText}>{label}</span>
      {children}
    </label>
  );
}

